def resolve(path, cwd, links):
    # Track the number of links followed
    links_followed = 0
    max_links = 8

    # Normalize the starting path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component to current path
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if candidate is a symlink
        if candidate in links:
            links_followed += 1
            if links_followed > max_links:
                return None

            target = links[candidate]

            # Resolve the target path relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                new_components = target.split('/')[1:]
            else:
                # Relative target - relative to the directory containing the link
                link_dir = candidate.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                current = link_dir
                new_components = target.split('/')

            # Insert remaining components from the original path
            components = new_components + components[i:]
            i = 0
        else:
            current = candidate

    # Validate that the result is a canonical absolute path
    if not current.startswith('/'):
        return None

    # Remove trailing slash (except for '/')
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

